memoryLeaks.example:
#include <stdlib.h>

int main() {
    // Memory leak example
    int *leak = (int*)malloc(sizeof(int) * 10);
    // Forgot to free the allocated memory
    return 0;
}

invalidAccess.example:
#include <stdlib.h>

int main() {
    // Invalid read/write example
    int *arr = (int*)malloc(sizeof(int) * 5);
    arr[5] = 10;  // Out of bounds access
    free(arr);
    return 0;
}

