doubleFree.example:
#include <stdlib.h>

int main() {
    int *ptr = (int*)malloc(sizeof(int));
    free(ptr);
    free(ptr);  // Double free
    return 0;
}

mismatchedFree.example:
#include <stdlib.h>

int main() {
    int *arr = (int*)malloc(10 * sizeof(int));
    delete[] arr;  // Wrong deallocation function
    return 0;
}

overlappingMemory.example:
#include <string.h>

int main() {
    char str[20] = "Hello, World!";
    memcpy(str + 5, str, 10);  // Overlapping memory
    return 0;
}
